import json
import itertools

def solve_puzzle():
    # Input variables (categories and clues)
    houses = [1, 2, 3]  # House numbers left (1) to right (3)
    names = ["Eric", "Arnold", "Peter"]
    book_genres = ["mystery", "science fiction", "romance"]
    vacations = ["mountain", "beach", "city"]

    solution = None

    # Iterate over all permutations for assignments per house index (0->house1, 1->house2, 2->house3)
    for name_perm in itertools.permutations(names):
        # Clue 1: Eric is directly left of Arnold.
        idx_eric = name_perm.index("Eric")
        idx_arnold = name_perm.index("Arnold")
        if idx_arnold != idx_eric + 1:
            continue

        for book_perm in itertools.permutations(book_genres):
            # Clue 5: Science fiction books is the person who loves beach vacations (handled later with vacations)
            # Clue 4: The person who loves mystery books is somewhere to the left of the person who loves beach vacations (needs vacations)
            # We'll enforce after picking vacations.

            for vac_perm in itertools.permutations(vacations):
                # Create index lookups by attribute -> house index (0-based)
                name_to_idx = {name_perm[i]: i for i in range(3)}
                book_to_idx = {book_perm[i]: i for i in range(3)}
                vac_to_idx = {vac_perm[i]: i for i in range(3)}

                # Clue 3: Peter is the person who prefers city breaks.
                if name_to_idx["Peter"] != vac_to_idx["city"]:
                    continue

                # Clue 2: Peter is somewhere to the right of the person who loves beach vacations.
                if not (name_to_idx["Peter"] > vac_to_idx["beach"]):
                    continue

                # Clue 4: The person who loves mystery books is somewhere to the left of the person who loves beach vacations.
                if not (book_to_idx["mystery"] < vac_to_idx["beach"]):
                    continue

                # Clue 5: The person who loves science fiction books is the person who loves beach vacations.
                if book_to_idx["science fiction"] != vac_to_idx["beach"]:
                    continue

                # If all constraints satisfied, we found a solution
                solution = {
                    "header": ["House", "Name", "BookGenre", "Vacation"],
                    "rows": [
                        [str(1), name_perm[0], book_perm[0], vac_perm[0]],
                        [str(2), name_perm[1], book_perm[1], vac_perm[1]],
                        [str(3), name_perm[2], book_perm[2], vac_perm[2]],
                    ],
                }
                return {"solution": solution}

    # If no solution found (should not happen for a valid puzzle)
    return {"solution": {"header": ["House", "Name", "BookGenre", "Vacation"], "rows": []}}

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, ensure_ascii=False))
